import{_ as e,c as t,o as a,f as s}from"./chunks/framework.BOAZPCR7.js";const u=JSON.parse('{"title":"Mutational constraints on RSV F and its neutralization by antibodies","description":"","frontmatter":{"layout":"post","title":"Mutational constraints on RSV F and its neutralization by antibodies","date":"2026-09-15T00:00:00.000Z","author":"Jesse Bloom","head":[["link",{"rel":"canonical","href":"https://jbloomlab.org/posts/2026-09-15_rsv_dms.html"}]]},"headers":[],"relativePath":"posts/2026-09-15_rsv_dms.md","filePath":"posts/2026-09-15_rsv_dms.md"}'),o={name:"posts/2026-09-15_rsv_dms.md"},n=s('<p>Our study led by Cassie Simonich that characterizes how mutations to RSV F affect monoclonal antibodies was <a href="https://www.nature.com/articles/s41586-026-11030-4" target="_blank" rel="noreferrer">just published in <em>Nature</em></a>. This paper uses pseudovirus deep mutational scanning to measure how all F mutations affect clinical antibodies nirsevimab and clesrovimab, and provides a biophysical model that explains why escape from nirsevimab is more commonly observed in subtype B than A.</p><hr><p>Antibodies against RSV have dramatically reduced infant hospitalizations in the United States. But resistance is a concern that needs to be monitored. In this study, Cassie used pseudovirus deep mutational scanning to measure how all mutations to F affect neutralization by current clinical antibodies as well as past antibodies and new ones in clinical development.</p><p>She also showed how nirsevimab has reduced Fab potency to RSV subtype B, and how this explains the greater rate of resistance in that subtype.</p><p>To access and view the deep mutational scanning data, see <a href="https://dms-vep.org/RSV_Long_F_DMS/" target="_blank" rel="noreferrer">https://dms-vep.org/RSV_Long_F_DMS/</a>.</p><p>To see a Nexstrain tree that uses the data to score current sequences for their antibody escape, see <a href="https://dms-vep.org/RSV_Long_F_DMS/nextstrain_tree.html" target="_blank" rel="noreferrer">here</a>.</p><p>For more explanation about the biophysical model, see <a href="https://jbloomlab.github.io/IgG-vs-Fab-neutralization/notebook.html" target="_blank" rel="noreferrer">here</a>.</p><p>For some slides about this project, see <a href="https://slides.com/jbloom/grc-2026" target="_blank" rel="noreferrer">https://slides.com/jbloom/grc-2026</a>.</p>',8),r=[n];function i(l,d,c,p,h,m){return a(),t("div",null,r)}const b=e(o,[["render",i]]);export{u as __pageData,b as default};
